64	export class ShareButton {
65	  private readonly button: HTMLButtonElement;
66	  private readonly clipboard: ClipboardPort;
67	  private readonly urlProvider: UrlProvider;
68	  private readonly notifier: ToastNotifier;
69	  private readonly successText: string;
70	  private readonly failText: string;
71	
72	  constructor(
73	    button: HTMLButtonElement,
74	    deps: {
75	      clipboard: ClipboardPort;
76	      urlProvider: UrlProvider;
77	      notifier: ToastNotifier;
78	      successText?: string;
79	      failText?: string;
80	    },
81	  ) {
82	    this.button = button;
83	    this.clipboard = deps.clipboard;
84	    this.urlProvider = deps.urlProvider;
85	    this.notifier = deps.notifier;
86	    this.successText = deps.successText ?? SHARE_BUTTON.successText;
87	    this.failText = deps.failText ?? SHARE_BUTTON.failText;
88	  }
89	
90	  mount(): void {
91	    if (this.button.dataset[SHARE_BUTTON.boundAttr] === "true") return;
92	    this.button.dataset[SHARE_BUTTON.boundAttr] = "true";
93	    this.button.addEventListener("click", () => void this.handleClick());
94	  }
95	
96	  private async handleClick(): Promise<void> {
97	    const override = this.button.dataset.copyUrl;
98	    const url =
99	      override && override.trim() !== ""
100	        ? override
101	        : this.urlProvider.getCurrentUrl();
102	    try {
103	      await this.clipboard.writeText(url);
104	      this.notifier.setVisibleOn(this.successText, "success");
105	    } catch (error) {
106	      this.notifier.setVisibleOn(this.failText, "error");
107	    }
108	  }
109	
110	  
111	  static init(options: ShareButtonInitOptions | string = {}): void {
112	    const selector =
113	      typeof options === "string"
114	        ? options
115	        : (options.selector ?? SHARE_BUTTON.selector);
116	    const root =
117	      typeof options === "string" ? document : (options.root ?? document);
118	    const buttons = root.querySelectorAll<HTMLButtonElement>(selector);
119	    if (buttons.length === 0) return;
120	
121	    const clipboard = new BrowserClipboardPort();
122	    const urlProvider = new WindowUrlProvider();
123	    const notifier = new Toast();
124	
125	    buttons.forEach((button) => {
126	      const share = new ShareButton(button, {
127	        clipboard,
128	        urlProvider,
129	        notifier,
130	        successText: button.dataset.copySuccessText ?? SHARE_BUTTON.successText,
131	        failText: button.dataset.copyFailText ?? SHARE_BUTTON.failText,
132	      });
133	      share.mount();
134	    });
135	  }
136	}
