145	export class MagneticCornerTracker {
146	  private static _globalInstances: MagneticCornerTracker[] = [];
147	
148	  private readonly gsap: MagneticCornerGsap;
149	  private readonly cfg: Required<Omit<MagneticCornerTrackerOptions, "root">>;
150	  private readonly H = { x0: 0, y0: 0, x1: 100, y1: 50, L: 20, p: 0 };
151	  private readonly cache: Record<string, string | number> = {} as Record<
152	    string,
153	    string | number
154	  >;
155	  private hoverEl: HTMLElement | null = null;
156	  private hoverTween: { kill?: () => void } | null = null;
157	  private progressTween: { kill?: () => void } | null = null;
158	  private dirty = false;
159	  private rafId = 0;
160	  private pendingMove: {
161	    el: HTMLElement;
162	    txt: HTMLElement | null;
163	    x: number;
164	    y: number;
165	  } | null = null;
166	  private moveScheduled = false;
167	  private readonly rectCache = new Map<HTMLElement, MagneticCornerBox>();
168	  private readonly arms: Record<string, SVGPathElement>;
169	  private readonly svg: SVGSVGElement;
170	  private readonly onScrollOrResize: () => void;
171	  private _mounted = false;
172	
173	  constructor(
174	    opts: MagneticCornerTrackerOptions,
175	    gsapInstance: MagneticCornerGsap,
176	  ) {
177	    this.gsap = gsapInstance;
178	    const d = MAGNETIC_CORNER_DEFAULTS;
179	    this.cfg = {
180	      gap: opts.gap ?? d.gap,
181	      pull: opts.pull ?? d.pull,
182	      pullText: opts.pullText ?? d.pullText,
183	      cornerFollow: opts.cornerFollow ?? opts.pull ?? d.pull,
184	      color: opts.color ?? d.color,
185	    };
186	    this.svg = this.buildSvg();
187	    this.arms = this.buildArms();
188	    this.onScrollOrResize = (): void => {
189	      this.rectCache.clear();
190	    };
191	  }
192	
193	  mount(scope: HTMLElement | null, linkSelector: string): void {
194	    if (this._mounted) return;
195	    this._mounted = true;
196	    window.addEventListener("scroll", this.onScrollOrResize, { passive: true });
197	    window.addEventListener("resize", this.onScrollOrResize);
198	    const parent = scope ?? document.body;
199	    parent.appendChild(this.svg);
200	    this.rafLoop();
201	    const elements = scope
202	      ? scope.querySelectorAll<HTMLElement>(linkSelector)
203	      : document.querySelectorAll<HTMLElement>(linkSelector);
204	    this.bind(elements);
205	  }
