259	  private buildSvg(): SVGSVGElement {
260	    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
261	    Object.assign(svg.style, {
262	      position: "fixed",
263	      inset: "0",
264	      width: "100%",
265	      height: "100%",
266	      pointerEvents: "none",
267	      zIndex: "101",
268	      overflow: "visible",
269	    });
270	    return svg;
