151	class FeatureCardCanvasRuntime {
152	  private _instances: FeatureCardCanvasInstance[] = [];
153	  private _rafId: number | null = null;
154	  private _resizeListener: (() => void) | null = null;
155	
156	  init(root?: ParentNode | null): void {
157	    this.dispose();
158	    const scope = root ?? document;
159	    const cardList = scope.querySelector<HTMLElement>(
160	      FEATURE_CARD_CANVAS.listSelector,
161	    );
162	    if (!cardList) return;
163	    const canvasElements = Array.from(
164	      cardList.querySelectorAll<HTMLCanvasElement>(
165	        FEATURE_CARD_CANVAS.canvasSelector,
166	      ),
167	    );
168	    if (canvasElements.length === 0) return;
169	
170	    this._instances = canvasElements.flatMap((canvas, index) => {
171	      const context = canvas.getContext("2d");
172	      if (!context) return [];
173	      return [
174	        {
175	          canvas,
176	          context,
177	          size: { width: 0, height: 0, dpr: 1 },
178	          rotation: index * 0.45,
179	          tilt: 0.6 + index * 0.18,
180	          speed:
181	            FEATURE_CARD_CANVAS.rotationSpeedBase +
182	            index * FEATURE_CARD_CANVAS.rotationSpeedStep,
183	          particles: this._createParticles(index),
184	        },
185	      ];
186	    });
187	
188	    if (this._instances.length === 0) return;
189	
190	    this._resizeListener = () => this._resize();
191	    window.addEventListener("resize", this._resizeListener);
192	    this._resize();
193	    this._startLoop();
194	  }
195	
196	  dispose(): void {
197	    if (this._rafId !== null) {
198	      FrameScheduler.cancel(this._rafId);
199	      this._rafId = null;
200	    }
201	    if (this._resizeListener) {
202	      window.removeEventListener("resize", this._resizeListener);
203	      this._resizeListener = null;
204	    }
205	    this._instances = [];
206	  }
207	
208	  private _startLoop(): void {
209	    const render = (): void => {
210	      this._render();
211	      this._rafId = FrameScheduler.request(render);
212	    };
213	    render();
214	  }
215	
216	  private _resize(): void {
217	    const dpr = Math.min(
218	      ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio,
219	      FEATURE_CARD_CANVAS.pixelRatioMax,
220	    );
221	    this._instances.forEach((instance) => {
222	      const bounds = instance.canvas.getBoundingClientRect();
223	      const width = Math.max(1, Math.round(bounds.width));
224	      const height = Math.max(1, Math.round(bounds.height));
225	      instance.size = { width, height, dpr };
226	      instance.canvas.width = Math.round(width * dpr);
227	      instance.canvas.height = Math.round(height * dpr);
228	      instance.context.setTransform(dpr, 0, 0, dpr, 0, 0);
229	    });
230	  }
231	
232	  private _render(): void {
233	    this._instances.forEach((instance) => {
234	      const { context, size } = instance;
235	      if (size.width <= 0 || size.height <= 0) return;
236	
237	      instance.rotation += instance.speed;
238	      context.clearRect(0, 0, size.width, size.height);
239	      context.fillStyle = FEATURE_CARD_CANVAS.clearColor;
240	      context.fillRect(0, 0, size.width, size.height);
241	
242	      this._drawParticles(instance);
243	      this._drawCube(instance);
244	    });
245	  }
246	
247	  private _drawParticles(instance: FeatureCardCanvasInstance): void {
248	    const { context, size, rotation, particles } = instance;
249	    const halfWidth = size.width * 0.5;
250	    const halfHeight = size.height * 0.5;
251	    const scale =
252	      Math.min(size.width, size.height) * FEATURE_CARD_CANVAS.cubeScale;
253	
254	    context.fillStyle = FEATURE_CARD_CANVAS.particleColor;
255	    particles.forEach((particle) => {
256	      const spin = rotation * (0.6 + particle.drift * 0.4);
257	      const cos = Math.cos(spin);
258	      const sin = Math.sin(spin);
259	      const rotatedX = particle.x * cos - particle.z * sin;
260	      const rotatedZ = particle.x * sin + particle.z * cos;
261	      const depth = rotatedZ + 3.6;
262	      const perspective = 1 / depth;
263	      const drawX = halfWidth + rotatedX * scale * perspective;
264	      const drawY =
265	        halfHeight +
266	        (particle.y + Math.sin(rotation + particle.drift) * 0.14) *
267	          scale *
268	          perspective;
269	      const drawSize = particle.size * perspective * 4.5;
270	      context.fillRect(drawX, drawY, drawSize, drawSize);
271	    });
272	  }
273	
274	  private _drawCube(instance: FeatureCardCanvasInstance): void {
275	    const { context, size, rotation, tilt } = instance;
276	    const halfWidth = size.width * 0.5;
277	    const halfHeight = size.height * 0.5;
278	    const scale =
279	      Math.min(size.width, size.height) * FEATURE_CARD_CANVAS.cubeScale;
280	    const projected = FEATURE_CARD_CUBE_VERTICES.map(([x, y, z]) => {
281	      const rotatedY = this._rotateY(x, z, rotation);
282	      const rotatedX = this._rotateX(y, rotatedY.z, tilt);
283	      const depth = rotatedX.z + 4.2;
284	      const perspective = 1 / depth;
285	      return {
286	        x: halfWidth + rotatedY.x * scale * perspective,
287	        y: halfHeight + rotatedX.y * scale * perspective,
288	      };
289	    });
290	
291	    context.fillStyle = FEATURE_CARD_CANVAS.fillStyle;
292	    context.beginPath();
293	    context.moveTo(projected[4].x, projected[4].y);
294	    context.lineTo(projected[5].x, projected[5].y);
295	    context.lineTo(projected[6].x, projected[6].y);
296	    context.lineTo(projected[7].x, projected[7].y);
297	    context.closePath();
298	    context.fill();
299	
300	    context.strokeStyle = FEATURE_CARD_CANVAS.strokeStyle;
301	    context.lineWidth = 1.2;
302	    FEATURE_CARD_CUBE_EDGES.forEach(([startIndex, endIndex]) => {
303	      const start = projected[startIndex];
304	      const end = projected[endIndex];
305	      context.beginPath();
306	      context.moveTo(start.x, start.y);
307	      context.lineTo(end.x, end.y);
308	      context.stroke();
309	    });
310	  }
311	
312	  private _createParticles(index: number): FeatureCardCanvasParticle[] {
313	    return Array.from(
314	      { length: FEATURE_CARD_CANVAS.particleCount },
315	      (_, particleIndex) => {
316	        const seed = (index + 1) * (particleIndex + 3);
317	        const angle = seed * 0.73;
318	        const radius = 1.2 + (particleIndex % 5) * 0.18;
319	        return {
320	          x: Math.cos(angle) * radius,
321	          y: (((particleIndex % 7) - 3) / 3) * 1.35,
322	          z: Math.sin(angle) * radius,
323	          size:
324	            FEATURE_CARD_CANVAS.particleSizeMin +
325	            (particleIndex % 4) *
326	              ((FEATURE_CARD_CANVAS.particleSizeMax -
327	                FEATURE_CARD_CANVAS.particleSizeMin) /
328	                3),
329	          drift: 0.8 + (particleIndex % 6) * 0.12,
330	        };
331	      },
332	    );
333	  }
334	
335	  private _rotateY(
336	    x: number,
337	    z: number,
338	    angle: number,
339	  ): { x: number; z: number } {
340	    const cos = Math.cos(angle);
341	    const sin = Math.sin(angle);
342	    return {
343	      x: x * cos - z * sin,
344	      z: x * sin + z * cos,
345	    };
346	  }
347	
348	  private _rotateX(
349	    y: number,
350	    z: number,
351	    angle: number,
352	  ): { y: number; z: number } {
353	    const cos = Math.cos(angle);
354	    const sin = Math.sin(angle);
355	    return {
356	      y: y * cos - z * sin,
357	      z: y * sin + z * cos,
358	    };
359	  }
360	}
361	
362	export class PageRuntime {
363	  private controller: PageController | null = null;
364	  private bootTask: Promise<void> | null = null;
365	  private readonly _globalUiRuntime = new PageGlobalUiRuntime();
366	  private readonly _featureCardCanvasRuntime = new FeatureCardCanvasRuntime();
367	  private readonly _subpageStarfieldRuntime = new SubpageStarfieldRuntime();
368	
369	  async runPage(root?: HTMLElement): Promise<void> {
370	    if (this.bootTask) return this.bootTask;
371	
372	    this.bootTask = (async () => {
373	      this._disposePageRuntime();
374	      this.disposeController();
375	
376	      if ("scrollRestoration" in history) {
377	        history.scrollRestoration = "manual";
378	      }
379	      window.scrollTo({ top: 0, behavior: "auto" });
380	
381	      this._globalUiRuntime.init(root);
382	      this._featureCardCanvasRuntime.init(root);
383	      this._subpageStarfieldRuntime.init(root);
384	
385	      this.controller = new PageController();
386	      await this.controller.init(root);
387	    })().finally(() => {
388	      this.bootTask = null;
389	    });
390	
391	    return this.bootTask;
392	  }
393	
394	  syncAfterContainerChange(): void {
395	    this._globalUiRuntime.syncAfterContainerChange();
396	  }
397	
398	  disposeController(): void {
399	    this.controller?.dispose();
400	    this.controller = null;
401	    this.bootTask = null;
402	    TimelineRuntime.clear();
403	  }
404	
405	  dispose(): void {
406	    this.disposeController();
407	    this._disposePageRuntime();
408	    TimelineRuntime.clear();
409	  }
410	
411	  private _disposePageRuntime(): void {
412	    try {
413	      this._globalUiRuntime.dispose();
414	    } catch (error) {
415	      console.warn(
416	        "[PageRuntime._disposePageRuntime] Global UI cleanup failed.",
417	        error,
418	      );
419	    }
420	    try {
421	      this._featureCardCanvasRuntime.dispose();
422	    } catch (error) {
423	      console.warn(
424	        "[PageRuntime._disposePageRuntime] Feature card canvas cleanup failed.",
425	        error,
426	      );
427	    }
428	    try {
429	      this._subpageStarfieldRuntime.dispose();
430	    } catch (error) {
431	      console.warn(
432	        "[PageRuntime._disposePageRuntime] Subpage starfield cleanup failed.",
433	        error,
434	      );
435	    }
436	  }
437	}
