I now have everything I need. Here is the complete implementation plan.

---

## Implementation Plan: `no-btn-char` Character-Roll Button Component

### Design Decisions Resolved

**DOM building**: Auto-build from `data-char-btn` attribute. The component scans for `.no-btn-char[data-char-btn]` elements whose `__text` span contains only raw text (not already-built cells), splits each text node into individual characters, and wraps them in `__cell` / `__char--orig` / `__char--clone` spans. Elements already containing `.no-btn-char__cell` are skipped (idempotent, safe for server-pre-rendered HTML).

**Icon reveal**: Pure CSS `transition` only. The `--icon-reveal` modifier uses a CSS `transform` + `opacity` transition on `__icon--reveal` triggered by the parent's `:hover`. GSAP handles chars only.

**Stagger direction on leave**: Same left-to-right stagger on both enter and leave. This avoids a jarring "snap-back" effect since `power3.inOut` is symmetric, and keeps the code simpler. Reversing stagger on leave is an easy change if needed.

---

### File 1 — CREATE `resource/ts/components/CharBtn.ts`

```typescript
import { CHAR_BTN } from "../config/component.config.js";
import type {
  CharBtnInitOptions,
  CharBtnInstance,
} from "../types/component.types.js";
import type {
  GsapGlobal,
  WindowWithGsap,
} from "../types/gsap.types.js";

function getGsap(): GsapGlobal | null {
  return (window as WindowWithGsap).gsap ?? null;
}

// Builds __cell > __char--orig + __char--clone structure from a raw text node.
// Returns false if the element is already built (has __cell children).
function buildCells(textEl: HTMLElement): boolean {
  if (textEl.querySelector(`.${CHAR_BTN.cellClass}`)) return false;

  const raw = textEl.textContent ?? "";
  textEl.textContent = "";

  for (const char of raw) {
    const cell = document.createElement("span");
    cell.className = CHAR_BTN.cellClass;

    const orig = document.createElement("span");
    orig.className = `${CHAR_BTN.charClass} ${CHAR_BTN.origClass}`;
    orig.textContent = char;

    const clone = document.createElement("span");
    clone.className = `${CHAR_BTN.charClass} ${CHAR_BTN.cloneClass}`;
    clone.textContent = char;

    cell.appendChild(orig);
    cell.appendChild(clone);
    textEl.appendChild(cell);
  }

  return true;
}

class CharBtnInstance {
  private readonly _root: HTMLElement;
  private _origChars: HTMLElement[] = [];
  private _cloneChars: HTMLElement[] = [];
  private readonly _onEnter: () => void;
  private readonly _onLeave: () => void;

  constructor(root: HTMLElement) {
    this._root = root;
    this._onEnter = this._handleEnter.bind(this);
    this._onLeave = this._handleLeave.bind(this);
  }

  mount(): void {
    const textEl = this._root.querySelector<HTMLElement>(
      `.${CHAR_BTN.textClass}`
    );
    if (!textEl) return;

    buildCells(textEl);

    this._origChars = Array.from(
      textEl.querySelectorAll<HTMLElement>(`.${CHAR_BTN.origClass}`)
    );
    this._cloneChars = Array.from(
      textEl.querySelectorAll<HTMLElement>(`.${CHAR_BTN.cloneClass}`)
    );

    if (this._origChars.length === 0) return;

    this._root.dataset[CHAR_BTN.boundAttr] = "true";
    this._root.addEventListener("mouseenter", this._onEnter);
    this._root.addEventListener("mouseleave", this._onLeave);
  }

  destroy(): void {
    this._root.removeEventListener("mouseenter", this._onEnter);
    this._root.removeEventListener("mouseleave", this._onLeave);
    const gsap = getGsap();
    if (gsap) {
      gsap.killTweensOf?.(this._origChars);
      gsap.killTweensOf?.(this._cloneChars);
      gsap.set(this._origChars, { yPercent: 0 });
      gsap.set(this._cloneChars, { yPercent: 100 });
    }
    delete this._root.dataset[CHAR_BTN.boundAttr];
  }

  private _handleEnter(): void {
    const gsap = getGsap();
    if (!gsap) return;
    gsap.killTweensOf?.(this._origChars);
    gsap.killTweensOf?.(this._cloneChars);
    gsap.to(this._origChars, {
      yPercent: -100,
      duration: CHAR_BTN.duration,
      ease: CHAR_BTN.ease,
      stagger: CHAR_BTN.stagger,
      overwrite: "auto",
    });
    gsap.to(this._cloneChars, {
      yPercent: 0,
      duration: CHAR_BTN.duration,
      ease: CHAR_BTN.ease,
      stagger: CHAR_BTN.stagger,
      overwrite: "auto",
    });
  }

  private _handleLeave(): void {
    const gsap = getGsap();
    if (!gsap) return;
    gsap.killTweensOf?.(this._origChars);
    gsap.killTweensOf?.(this._cloneChars);
    gsap.to(this._origChars, {
      yPercent: 0,
      duration: CHAR_BTN.duration,
      ease: CHAR_BTN.ease,
      stagger: CHAR_BTN.stagger,
      overwrite: "auto",
    });
    gsap.to(this._cloneChars, {
      yPercent: 100,
      duration: CHAR_BTN.duration,
      ease: CHAR_BTN.ease,
      stagger: CHAR_BTN.stagger,
      overwrite: "auto",
    });
  }
}

export class CharBtn {
  private static _instances: CharBtnInstance[] = [];

  static init(options: CharBtnInitOptions = {}): void {
    CharBtn.dispose();
    const selector = options.selector ?? CHAR_BTN.selector;
    const root = options.root ?? document;
    const roots = Array.from(root.querySelectorAll<HTMLElement>(selector));
    if (roots.length === 0) return;

    CharBtn._instances = roots
      .filter((el) => !el.dataset[CHAR_BTN.boundAttr])
      .map((el) => {
        const instance = new CharBtnInstance(el);
        instance.mount();
        return instance;
      });
  }

  static dispose(): void {
    CharBtn._instances.forEach((instance) => instance.destroy());
    CharBtn._instances = [];
  }
}
```

**Key implementation notes:**
- `GsapGlobal` from `gsap.types.ts` has `killTweensOf` as optional (`killTweensOf?`). The code uses optional chaining accordingly.
- `overwrite: "auto"` handles rapid enter/leave toggling without double-tween artifacts.
- The `CharBtnInstance` class is file-scoped (not exported) to match the `MarqueeItemRuntime` pattern in `Marquee.ts`.
- `for...of` over a string correctly handles multi-byte Unicode characters (Korean etc.), unlike `split("")`.

---

